  height: calc(40vh - 120px) !important;
}

.banner-title {
  vertical-align: middle;
  width: 100%;
  font-size: 1.8em;
  position: absolute;
  top: 50%;
  left: 0;
  transform: translateY(-50%);
}

.banner-subtitle {
  opacity: .9;
  margin-top: 10px;
  font-size: 16px;
}

.banner-subtitle.typing-effect:after, .banner-title-inner.typing-effect:after {
  animation: 1s forwards cursor-flash-effect;
  animation-iteration-count: var(--animation-cnt);
  content: "";
  outline: 1px solid #fff;
  width: 0;
  height: 30px;
  display: inline-block;
  transform: translateX(5px)translateY(5px);
}

.banner-subtitle.typing-effect:after {
  opacity: .9;
  outline: .5px solid #fff;
  height: 16px;
  transform: translateX(5px)translateY(2px);
}

@keyframes cursor-flash-effect {
  0% {
    opacity: 0;
  }

  15% {
    opacity: 1;
  }

  50% {
    opacity: 1;
  }

  65% {
    opacity: 0;
  }

  to {
    opacity: 0;
  }
}

