  border: none;
  border-radius: 100px;
  width: 42px;
  height: 42px;
  margin-top: 6px;
  margin-right: 10px;
  padding: 0;
  font-size: 25px;
  transition: all .3s;
  transform: none;
  color: inherit !important;
  background: none !important;
}

#comment_emotion_btn:hover {
  transform: scale(1.1);
}

#comment_emotion_btn.comment-emotion-keyboard-open {
  border-radius: 100px;
  transform: scale(1.1);
  color: var(--themecolor) !important;
}

.emotion-keyboard {
  opacity: 0;
  pointer-events: none;
  transform-origin: 100% 0;
  z-index: 1000;
  flex-direction: column;
  min-width: min(300px, 100vw - 40px);
  max-width: min(500px, 100vw - 40px);
  height: 300px;
  margin-top: 10px;
  transition: all .3s;
  position: absolute;
  top: 100%;
  right: 0;
  overflow: hidden;
  transform: scale(.9);
  display: none !important;
}

#comment_emotion_btn.comment-emotion-keyboard-open + .emotion-keyboard {
  opacity: 1;
  pointer-events: all;
  transform: scale(1);
  display: flex !important;
}

.emotion-keyboard-content {
  flex: 1;
  overflow-y: auto;
}

.emotion-group {
  padding: 15px 15px 10px;
}

.emotion-item {
  background: var(--color-border-on-foreground);
  cursor: pointer;
  user-select: none;
  border-radius: 5px;
  margin-bottom: 12px;
  margin-right: 12px;
  padding: 2px 10px;
  transition: all .3s;
  display: inline-block;
}

.emotion-item.emotion-item-sticker, .emotion-item.emotion-item-video {
  background: #7d7d7d26;
  padding: 2px;
}

.emotion-item.emotion-item-sticker:hover > img[src^="data:image/svg+xml;base64,PHN2ZyBjbGFzcz0iZW1vdGlvbi1sb2FkaW5nI"], .emotion-item.emotion-item-video:hover > img[src^="data:image/svg+xml;base64,PHN2ZyBjbGFzcz0iZW1vdGlvbi1sb2FkaW5nI"] {
  filter: brightness(2);
}

.emotion-item > img, .emotion-item > video {
  background: var(--color-widgets);
  vertical-align: top;
  border-radius: 3px;
  max-height: 60px;
  transition: filter .3s, transform .3s;
}

.emotion-item > video {
  max-height: 90px;
}

.emotion-item:hover {
  background: var(--themecolor);
  color: #fff;
}

.emotion-group:active .emotion-item:hover > img:not([src^="data:image/svg+xml;base64,PHN2ZyBjbGFzcz0iZW1vdGlvbi1sb2FkaW5nI"]), .emotion-group:active .emotion-item:hover > video {
  transition: all .3s .3s;
  transform: scale(1.5);
  box-shadow: 0 0 5px #00000026;
}

.emotion-group-description {
  opacity: .6;
  text-align: right;
  font-size: 14px;
}

.emotion-keyboard-bar {
  white-space: nowrap;
  overflow-x: auto;
  transform: scaleY(-1);
  box-shadow: 0 .125rem .25rem #0000000f;
}

.emotion-keyboard-bar::-webkit-scrollbar-track {
  background: none;
}

.emotion-keyboard-bar::-webkit-scrollbar {
  height: 5px;
}

.emotion-keyboard-bar::-webkit-scrollbar-thumb {
  background-color: #0003;
  border: none;
}

.emotion-keyboard-bar::-webkit-scrollbar-thumb:hover {
  background-color: var(--themecolor);
}

.emotion-group-name {
  cursor: pointer;
  user-select: none;
  padding: 10px 20px;
  transition: all .3s;
  display: inline-block;
  position: relative;
  transform: scaleY(-1);
}

.emotion-group-name:hover {
  background: var(--color-border-on-foreground);
}

.emotion-group-name.active:after {
  background: var(--themecolor);
  content: "";
  pointer-events: none;
  height: 3px;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
}

.related-posts {
  white-space: nowrap;
  margin-bottom: 25px;
  padding: 0;
  display: block;
}

.related-posts > h2 {
  margin-top: 1.2rem;
  margin-left: 1.5rem;
  margin-right: 1.5rem;
}

.related-posts .related-post-container {
  padding: .8rem 1.5rem;
  overflow-x: auto;
}

.related-post-card {
  background: var(--themecolor-gradient);
  white-space: normal;
  border-radius: 5px;
  width: 180px;
  height: 105px;
  margin-right: 10px;
  font-size: 16px;
  line-height: 27px;
  transition: all .3s;
  display: inline-block;
  position: relative;
  overflow: hidden;
}

.related-post-card:hover {
  filter: brightness(.9);
  border-color: #0000;
  box-shadow: 0 4px 6px #32325d1c, 0 1px 3px #00000014;
}

.related-post-title.clamp {
  color: #fff;
}

.related-post-card-container {
  padding: 10px 15px;
  position: absolute;
  inset: 0;
}

.related-post-card-container.has-thumbnail {
  color: #fff;
  background: #0003;
  transition: all .3s;
}

.related-post-card-container.has-thumbnail:hover {
  background: #0000004d;
}

.related-post-title {
  max-height: 81px;
  overflow: hidden;
}

.related-post-arrow {
  pointer-events: none;
  font-size: 15px;
  position: absolute;
  bottom: 15px;
  right: 15px;
}

.related-post-thumbnail {
  object-fit: cover;
  width: 100%;
  height: 100%;
}

img.related-post-thumbnail {
  vertical-align: unset;
}

i.related-post-arrow.fa.fa-chevron-right {
  color: #fff;
}

html.darkmode a.related-post-card {
  background: var(--color-border-on-foreground);
  border-radius: 5px;
}

html.darkmode .related-post-title.clamp {
  color: var(--themecolor-light);
}

html.darkmode .has-thumbnail .related-post-title.clamp {
  color: #eee;
}
